INSERT INTO t_p98221464_innovative_solution_.materials (name, category, price, unit, description, image_url, in_stock, sort_order, archived) VALUES ('Газосиликатный блок D600 600×200×400', 'bloki', '5 100 ₽', 'м³', 'Производство г. Бор. Размер 600×200×400 мм. Плотность D600. В упаковке (на поддоне) 1,92 м³ — 40 шт. Вес поддона 1500 кг. Толстый автоклавный блок для тёплых несущих стен без утепления: ровная геометрия под кладку на клей. Доставка манипулятором с разгрузкой.', '/img/gazoblok-600-200-400.jpg', true, 1, false);